CREATE TRIGGER trg_activity_fields_owner_immutable
BEFORE UPDATE OF activity_type_id ON activity_fields
WHEN OLD.activity_type_id IS NOT NEW.activity_type_id
BEGIN
  SELECT RAISE(ABORT, 'activity_field_owner_immutable');
END;

